public static class MultiAxisStockHost {
 const string Pin="3cdd4f54ef94e6b95f2a149dad246b4e73aad4e9",Core="3405064ebc312dbe38bacfdfb0eea8015354447ae3f749e4089cb8f584d1351d";
 static volatile bool cancelled;static void Check(){if(cancelled)throw new OperationCanceledException();}
 static string Hash(string p)=>Convert.ToHexString(SHA256.HashData(File.ReadAllBytes(p))).ToLowerInvariant();
 public readonly record struct D(double X,double Y,double Z){public static D operator +(D a,D b)=>new(a.X+b.X,a.Y+b.Y,a.Z+b.Z);public static D operator -(D a,D b)=>new(a.X-b.X,a.Y-b.Y,a.Z-b.Z);public static D operator *(D a,double s)=>new(a.X*s,a.Y*s,a.Z*s);public double Length=>Math.Sqrt(X*X+Y*Y+Z*Z);public static double Dot(D a,D b)=>a.X*b.X+a.Y*b.Y+a.Z*b.Z;public D Unit()=>this*(1/Length);public Vector3 F()=>new((float)X,(float)Y,(float)Z);public double[] A()=>new[]{X,Y,Z};}
 readonly record struct Q(double X,double Y,double Z,double W){public Q Unit(){double n=Math.Sqrt(X*X+Y*Y+Z*Z+W*W);return new(X/n,Y/n,Z/n,W/n);}public static Q Axis(D n){n=n.Unit();return n.Z<(-1+1e-14)?new Q(1,0,0,0):new Q(-n.Y,n.X,0,1+n.Z).Unit();}public static double Dot(Q a,Q b)=>a.X*b.X+a.Y*b.Y+a.Z*b.Z+a.W*b.W;public Q Neg()=>new(-X,-Y,-Z,-W);public static Q Mix(Q a,Q b,double t){double dot=Dot(a,b);if(dot<0){b=b.Neg();dot=-dot;}if(dot>0.9999999999)return new Q(a.X*(1-t)+b.X*t,a.Y*(1-t)+b.Y*t,a.Z*(1-t)+b.Z*t,a.W*(1-t)+b.W*t).Unit();double angle=Math.Acos(Math.Clamp(dot,-1,1)),s=Math.Sin(angle),u=Math.Sin((1-t)*angle)/s,v=Math.Sin(t*angle)/s;return new(a.X*u+b.X*v,a.Y*u+b.Y*v,a.Z*u+b.Z*v,a.W*u+b.W*v);}public D AxisZ()=>new D(2*(X*Z+W*Y),2*(Y*Z-W*X),1-2*(X*X+Y*Y)).Unit();}
 sealed record InputPose(D Tip,D Axis,Q Quaternion,ToolOrientation Native);
 sealed record Sample(D Tip,D Axis,Vector3 NativeTip,Vector3 NativeAxis,int Segment,int Index,int Steps);
 static D Vec(JsonElement e){var a=e.EnumerateArray().Select(x=>x.GetDouble()).ToArray();if(a.Length!=3||a.Any(v=>!double.IsFinite(v)||Math.Abs(v)>100))throw new ArgumentException("finite bounded XYZ/IJK required");return new(a[0],a[1],a[2]);}
 static void Keys(JsonElement o,params string[] allowed){if(o.ValueKind!=JsonValueKind.Object||o.EnumerateObject().Any(x=>!allowed.Contains(x.Name)))throw new ArgumentException("unsupported input fields; no machine/rotary/G-code authority inferred");}
 static double CylinderSdf(D p,Sample sample,double r,double l){D v=p-sample.Tip;double h=D.Dot(v,sample.Axis),radial=Math.Sqrt(Math.Max(0,D.Dot(v,v)-h*h))-r,axial=Math.Abs(h-l/2)-l/2;return Math.Min(Math.Max(radial,axial),0)+Math.Sqrt(Math.Pow(Math.Max(radial,0),2)+Math.Pow(Math.Max(axial,0),2));}
 static VoxelGrid Grid(D lo,D hi,double h)=>new(new BoundingBox(lo.F(),hi.F()),(float)h){UseParallelRemoval=false};
 static void PosedCylinder(VoxelGrid grid,Sample s,double radius,double length,double margin){double r=radius+margin,l=length+2*margin;if(r<=0||l<=0)throw new ArgumentException("resolution leaves no nonempty conservative cutter; refine the stock grid");Vector3 start=s.NativeTip-s.NativeAxis*(float)margin,end=s.NativeTip+s.NativeAxis*(float)(length+margin);grid.RemoveVoxelsInCylinder(start,end,(float)r,true);}
 static void WriteGrid(VoxelGrid g,D lo,double h,string path){using var w=new BinaryWriter(File.Create(path));w.Write(Encoding.ASCII.GetBytes("FLSTK001"));var n=g.Dimensions;w.Write(n.X);w.Write(n.Y);w.Write(n.Z);w.Write((float)h);w.Write((float)lo.X);w.Write((float)lo.Y);w.Write((float)lo.Z);for(int z=0;z<n.Z;z++){Check();for(int y=0;y<n.Y;y++)for(int x=0;x<n.X;x++)w.Write((byte)(g.GetVoxel(x,y,z)?1:0));}}
 static long FaceBudget(VoxelGrid g){long n=0;var d=g.Dimensions;for(int z=0;z<d.Z;z++){Check();for(int y=0;y<d.Y;y++)for(int x=0;x<d.X;x++)if(g.GetVoxel(x,y,z)){if(!g.GetVoxel(x-1,y,z))n++;if(!g.GetVoxel(x+1,y,z))n++;if(!g.GetVoxel(x,y-1,z))n++;if(!g.GetVoxel(x,y+1,z))n++;if(!g.GetVoxel(x,y,z-1))n++;if(!g.GetVoxel(x,y,z+1))n++;if(n>200000)throw new ArgumentException("surface budget exceeded");}}return n;}
 public static int Main(string[] args){try{return Run(args);}catch(Exception e){Console.Error.WriteLine(e);return e is OperationCanceledException?130:1;}}
