  if(args.Length!=3)throw new ArgumentException("input.json new-output-directory expected-input-SHA256");string input=Path.GetFullPath(args[0]),output=Path.GetFullPath(args[1]);if(Directory.Exists(output)||File.Exists(output))throw new IOException("output exists; never replay or replace an old result");if(new FileInfo(input).Length>65536||Hash(input)!=args[2])throw new ArgumentException("frozen input digest/budget mismatch");if(Hash(typeof(CutterSimulator).Assembly.Location)!=Core)throw new ArgumentException("core digest mismatch");
  using var timeout=new System.Threading.Timer(_=>cancelled=true,null,45000,System.Threading.Timeout.Infinite);Console.CancelKeyPress+=(_,e)=>{e.Cancel=true;cancelled=true;};using var doc=JsonDocument.Parse(File.ReadAllBytes(input));var q=doc.RootElement;Keys(q,"schema","units","qualificationID","sourceReference","stock","tool","sampling","poses");if(q.GetProperty("schema").GetString()!="floe.multi-axis-stock.v1"||q.GetProperty("units").GetString()!="mm")throw new ArgumentException("schema/units refused");
  var stock=q.GetProperty("stock");Keys(stock,"minMM","maxMM","resolutionMM");D lo=Vec(stock.GetProperty("minMM")),hi=Vec(stock.GetProperty("maxMM"));double h=stock.GetProperty("resolutionMM").GetDouble();if(!(new[]{0.25,0.5,1.0}).Contains(h))throw new ArgumentException("resolution must be .25/.5/1mm");var ext=hi-lo;double[] sizes=ext.A();if(sizes.Any(x=>x/h<1||x/h!=Math.Round(x/h))||lo.A().Any(x=>x!=(double)(float)x))throw new ArgumentException("explicit blank must be positive and exactly grid-aligned; no hidden blank extension");long cells=sizes.Select(x=>(long)Math.Round(x/h)).Aggregate(1L,(a,b)=>checked(a*b));if(cells>131072)throw new ArgumentException("cell budget exceeded");
  var tool=q.GetProperty("tool");Keys(tool,"kind","radiusMM","lengthMM");if(tool.GetProperty("kind").GetString()!="flat-end-mill")throw new ArgumentException("only axisymmetric flat cutter qualified");double radius=tool.GetProperty("radiusMM").GetDouble(),length=tool.GetProperty("lengthMM").GetDouble();if(!double.IsFinite(radius)||!double.IsFinite(length)||radius<1||radius>10||length<2||length>25)throw new ArgumentException("cutter budget");
  var settings=q.GetProperty("sampling");Keys(settings,"maxLinearStepMM","maxAngularStepDegrees","maxChordErrorMM");var nativeSettings=new SimulationSettings{MaxLinearStep=settings.GetProperty("maxLinearStepMM").GetSingle(),MaxAngularStep=settings.GetProperty("maxAngularStepDegrees").GetSingle(),MaxChordError=settings.GetProperty("maxChordErrorMM").GetSingle()};if(nativeSettings.MaxLinearStep<.05||nativeSettings.MaxLinearStep>1||nativeSettings.MaxAngularStep<.1||nativeSettings.MaxAngularStep>2||nativeSettings.MaxChordError<.0001||nativeSettings.MaxChordError>.01)throw new ArgumentException("sampling budget");
  var poses=new List<InputPose>();foreach(var pose in q.GetProperty("poses").EnumerateArray()){Keys(pose,"tipMM","axisTowardSpindle");D tip=Vec(pose.GetProperty("tipMM")),axis=Vec(pose.GetProperty("axisTowardSpindle"));if(axis.Length<1e-8)throw new ArgumentException("zero tool axis");poses.Add(new(tip,axis.Unit(),Q.Axis(axis),ToolOrientation.FromAxisTowardSpindle(axis.F())));}if(poses.Count<2||poses.Count>9)throw new ArgumentException("2..9 real poses required");if(!poses.Skip(1).Where((x,i)=>D.Dot(x.Axis,poses[i].Axis)<.9998).Any())throw new ArgumentException("this research adapter requires a varying tool axis; fixed-Z belongs to the existing basic adapter");
  var samples=new List<Sample>();var spans=new List<object>();double motionBound=0;int totalSteps=0;double nativeRadius=Math.Sqrt(2*radius*radius+length*length),pointRadius=Math.Sqrt(radius*radius+length*length);
  for(int k=0;k<poses.Count-1;k++){var a=poses[k];var b=poses[k+1];double d=(b.Tip-a.Tip).Length;if(d>50)throw new ArgumentException("segment length budget");double angle=2*Math.Acos(Math.Clamp(Math.Abs(Q.Dot(a.Quaternion,b.Quaternion)),0,1));if(angle>150*Math.PI/180)throw new ArgumentException("adjacent orientation exceeds the150degree qualified shortest-path bound");int n=nativeSettings.ComputeSteps(Vector3.Distance(a.Tip.F(),b.Tip.F()),ToolOrientation.AngularDistanceDegrees(a.Native,b.Native),(float)nativeRadius);if(n>1024)throw new ArgumentException("pose budget");totalSteps+=n;double delta=d/(2*n)+2*pointRadius*Math.Sin(angle/(4*n));motionBound=Math.Max(motionBound,delta);spans.Add(new{segment=k,steps=n,tipDistanceMM=d,angleRad=angle,motionEnvelopeMM=delta});
   Quaternion qa=a.Native.GetQuaternion(),qb=b.Native.GetQuaternion();for(int j=0;j<=n;j++){double t=j/(double)n;float tf=j/(float)n;D idealTip=a.Tip*(1-t)+b.Tip*t,idealAxis=Q.Mix(a.Quaternion,b.Quaternion,t).AxisZ();Vector3 nativeTip=Vector3.Lerp(a.Tip.F(),b.Tip.F(),tf),nativeAxis=Vector3.Normalize(Vector3.Transform(Vector3.UnitZ,Quaternion.Slerp(qa,qb,tf)));samples.Add(new(idealTip,idealAxis,nativeTip,nativeAxis,k,j,n));}}
  if(cells*samples.Count>120000000)throw new ArgumentException("cell/pose certificate budget exceeded");Check();var nominal=Grid(lo,hi,h);var lower=Grid(lo,hi,h);var upper=Grid(lo,hi,h);var sim=new CutterSimulator(nominal);sim.Settings.MaxLinearStep=nativeSettings.MaxLinearStep;sim.Settings.MaxAngularStep=nativeSettings.MaxAngularStep;sim.Settings.MaxChordError=nativeSettings.MaxChordError;
  var endmill=new EndMill((float)(2*radius),(float)length,false);for(int i=0;i<poses.Count-1;i++){Check();sim.CutLinearWithOrientation(poses[i].Tip.F(),poses[i+1].Tip.F(),endmill,poses[i].Native,poses[i+1].Native);}
  double cellRadius=Math.Sqrt(3)*h/2,numericPadding=.001;foreach(var sample in samples){Check();PosedCylinder(lower,sample,radius,length,motionBound+cellRadius+numericPadding);PosedCylinder(upper,sample,radius,length,-cellRadius-numericPadding);}
  // Independent double scalar witnesses certify EVERY cell. No correction/repainting of engine output.
  var dims=nominal.Dimensions;long innerWitnesses=0,outerWitnesses=0;double worstInner=double.NegativeInfinity,worstOuter=double.PositiveInfinity;for(int z=0;z<dims.Z;z++){Check();for(int y=0;y<dims.Y;y++)for(int x=0;x<dims.X;x++){bool low=lower.GetVoxel(x,y,z),mid=nominal.GetVoxel(x,y,z),up=upper.GetVoxel(x,y,z);if((low&&!mid)||(mid&&!up))throw new InvalidDataException("material envelope nesting failed");if(up&&!low)continue;D point=lo+new D(x+.5,y+.5,z+.5)*h;double sd=double.PositiveInfinity;foreach(var sample in samples)sd=Math.Min(sd,CylinderSdf(point,sample,radius,length));if(!up){if(!(sd<=-cellRadius-1e-9))throw new InvalidDataException("inner complete-cell certificate failed");worstInner=Math.Max(worstInner,sd);innerWitnesses++;}if(low){if(!(sd>=motionBound+cellRadius+1e-9))throw new InvalidDataException("outer complete-cell certificate failed");worstOuter=Math.Min(worstOuter,sd);outerWitnesses++;}}}
