  using(var csv=new StreamWriter(Path.Combine(staging,"evaluated-poses.tsv"))){csv.WriteLine("segment\tindex\tsteps\ttipX\ttipY\ttipZ\taxisI\taxisJ\taxisK");foreach(var s in samples)csv.WriteLine(FormattableString.Invariant($"{s.Segment}\t{s.Index}\t{s.Steps}\t{s.NativeTip.X:R}\t{s.NativeTip.Y:R}\t{s.NativeTip.Z:R}\t{s.NativeAxis.X:R}\t{s.NativeAxis.Y:R}\t{s.NativeAxis.Z:R}"));}
  string poseFile=Path.Combine(staging,"evaluated-poses.tsv");artifacts.Add(new{path="evaluated-poses.tsv",sha256=Hash(poseFile),bytes=new FileInfo(poseFile).Length});
  var manifest=new{schema="floe.multi-axis-stock-result.v1",status="computed-component-not-job-accepted",productReady=false,fullE38Accepted=false,inputSHA256=args[2],sourceReference=q.GetProperty("sourceReference").Clone(),qualificationID=q.GetProperty("qualificationID").GetString(),backend=new{sourcePin=Pin,coreSHA256=Core,hostSHA256=Hash(typeof(MultiAxisStockHost).Assembly.Location),actualOS=RuntimeInformation.OSDescription,architecture=RuntimeInformation.ProcessArchitecture.ToString(),runtime=Environment.Version.ToString()},trajectory="linear XYZ tip + canonical shortest quaternion slerp from IJK endpoints; no machine rotary joint/IK semantics",steps=totalSteps,evaluatedPoses=samples.Count,spans,motionEnvelopeMM=motionBound,voxelCellRadiusMM=cellRadius,numericEnvelopePaddingMM=numericPadding,precision="Voxel approximations. Continuous box-stock remaining VOLUME bracket by complete-cell witnesses; nominal mesh is sampled, not exact continuous sweep. No machine/fixture/holder safety.",material=new{nominalRemainingMM3=nominal.GetMaterialVolume(),continuousRemainingLowerMM3=lower.GetMaterialVolume(),continuousRemainingUpperMM3=upper.GetMaterialVolume(),nominalRemovedMM3=nominal.GetRemovedVolume(),lowerWitnesses=outerWitnesses,upperRemovedWitnesses=innerWitnesses,worstInnerSdf=double.IsInfinity(worstInner)?(double?)null:worstInner,worstOuterSdf=double.IsInfinity(worstOuter)?(double?)null:worstOuter},artifacts};
  File.WriteAllText(Path.Combine(staging,"manifest.json"),JsonSerializer.Serialize(manifest,new JsonSerializerOptions{WriteIndented=true}));Check();if(Hash(input)!=args[2])throw new IOException("input changed before artifact commit");Directory.Move(staging,output);Console.WriteLine(JsonSerializer.Serialize(new{status=manifest.status,manifestSHA256=Hash(Path.Combine(output,"manifest.json")),manifest.material,poses=samples.Count,motionEnvelopeMM=motionBound}));return 0;
